<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getNavigationMenuContext } from './navigation-menu-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), onkeydown, ...rest }: Props = $props(); const popover = getPopoverContext(); const navigation = getNavigationMenuContext(); function key(event: KeyboardEvent) { onkeydown?.(event as KeyboardEvent & { currentTarget: EventTarget & HTMLDivElement }); if (event.key === 'Escape') { navigation.setValue(null, event); popover.trigger?.focus(); } }</script>{#if navigation.value !== null}<div bind:this={ref} {...rest} onkeydown={key} data-open="" data-side={popover.side} data-align={popover.align}>{@render children?.()}</div>{/if}
